def _toc_hook(md, toc_item, state):
    """
    This function is a hook for the Markdown class to save TOC items into the state.env.
    Input-Output Arguments
    :param md: Markdown instance. The instance of the Markdown class.
    :param toc_item: String. The heading text.
    :param state: State instance. The instance of the State class.
    :return: No return values.
    """

    if toc_item['level'] >= min_level and toc_item['level'] <= max_level:
        anchor = striptags(toc_item['text']).replace(' ', '-')
        if heading_id:
            anchor = heading_id(anchor, toc_item)
        toc_item['id'] = anchor
        md.toc_items.append(toc_item)
        if toc_item['level'] > len(toc_tree):
            while len(toc_tree) < toc_item['level']:
                toc_tree.append([])
        else:
            while len(toc_tree) > toc_item['level']:
                del toc_tree[-1]
        toc_tree[-1].append(toc_item)

