def _toc_hook(md, state):
    if not state['md'].toc:
        return
    toc_headings = state['md'].toc_headings
    if len(toc_headings) < 1:
        return

    # Add heading id
    if heading_id is None:
        def default_heading_id(text, level):
            return 'toc_' + striptags(text).replace(' ', '_')
    else:
        default_heading_id = heading_id

    # Add to toc tree
    ul = etree.Element('ul')
    for toc_item in toc_headings:
        if toc_item['level'] < min_level or toc_item['level'] > max_level:
            # Skip the item
            continue
        while toc_item['level'] > min_level:
            # Close previous item
            element = ul[-1]
            if element.tag != 'ul':
                inner_ul = etree.Element('ul')
                element.append(inner_ul)
                ul = inner_ul
            else:
                ul = element
            element = ul[-1]
            if element.tag != 'li':
                li = etree.Element('li')
                ul.append(li)
                ul = li
            min_level += 1

        while toc_item['level'] < min_level:
            # Close previous item
            element = ul
            while element.getprevious() is not None:
                element = element.getprevious()
            if element.tag == 'ul':
                element.getparent().remove(element)
            min_level -= 1

        # Create a new list item
        li = etree.Element('li')
        ul[-1].append(li)
        html = etree.Element('a')
        html.text = toc_item

