def _render(tag, indent, pretty, xhtml, level):
  if pretty:
    if tag.is_pretty:
      if tag.is_single:
        return '%s<%s%s />' % (indent * level, tag.tag, tag.render_attributes())
      else:
        return '%s<%s%s>%s</%s>' % (indent * level, tag.tag, tag.render_attributes(),
          tag.render_children(indent, pretty, xhtml, level), tag.tag)
    else:
      if tag.is_single:
        return '%s<%s%s />' % (indent * level, tag.tag, tag.render_attributes())
      else:
        return '%s<%s%s>%s</%s>' % (indent * level, tag.tag, tag.render_attributes(),
          tag.render_children(indent, pretty, xhtml, level), tag.tag)
  else:
    if tag.is_single:
      return '<%s%s />' % (tag.tag, tag.render_attributes())
    else:
      return '<%s%s>%s</%s>' % (tag.tag, tag.render_attributes(),
        tag.render_children(indent, pretty, xhtml, level), tag.tag)

return _render(self, indent, pretty, xhtml, 0)

def _render_child(child, indent, pretty, xhtml):
  if isinstance(child, basestring):
    return child
  else:
    return child.render(indent, pretty, xhtml)

def _render_children(children, indent, pretty, xhtml):
  if not pretty:
