    for j in range(length):
        if i != j:
            matrix[i][j] = self._rate_sentence_pair(sentences[i], sentences[j])

# Normalize the matrix
for i in range(length):
    total = sum(matrix[i])
    if total > 0:
        for j in range(length):
            matrix[i][j] /= total

# Calculate the final ratings for each sentence
ratings = defaultdict(float)
