def _inspect_middleware_tree(middleware_components, parent=None):
    for component in middleware_components:
        source_info, name = _get_source_info_and_name(component)
        info = MiddlewareComponentInfo(name, source_info)
        middleware_tree.append((info, parent))
        if isinstance(component, falcon.routing.middleware.RoutingMiddleware):
            _inspect_middleware_tree(component._error_middleware, info)
            _inspect_middleware_tree(component._middleware, info)
            _inspect_middleware_tree(component._router._middleware, info)
            _inspect_middleware_tree(component._router._sinks, info)
            _inspect_middleware_tree(component._router._static_routes, info)
        elif isinstance(component, falcon.routing.compiled.CompiledRouter):
            _inspect_middleware_tree(component._error_middleware, info)
            _inspect_middleware_tree(component._middleware, info)
        elif isinstance(component, falcon.routing.compiled.CompiledSink):
            _inspect_middleware_tree(component._error_middleware, info)
            _inspect_middleware_tree(component._middleware, info)
        elif isinstance(component, falcon.routing.compiled.CompiledStaticSink):
            _inspect_middleware_tree(component._error_middleware, info)
            _inspect_middleware_tree(component._middleware, info)
        else:
            middleware_classes.append(info)

_inspect_middleware_tree(app._middleware)
return MiddlewareInfo(middleware_tree, middleware_classes)

