linear_hash = hashlib.sha256()
tree_hash = hashlib.sha256()

# Read the file in chunks
while True:
    chunk = fileobj.read(chunk_size)
    if not chunk:
        break
    linear_hash.update(chunk)
    tree_hash.update(chunk)

# Compute the tree hash
tree_hash_digest = tree_hash.digest()
while len(tree_hash_digest) > 1:
    tree_hash = hashlib.sha256()
    for i in range(0, len(tree_hash_digest), 2):
        if i + 1 < len(tree_hash_digest):
            tree_hash.update(tree_hash_digest[i] + tree_hash_digest[i + 1])
        else:
            tree_hash.update(tree_hash_digest[i])
    tree_hash_digest = tree_hash.digest()

# Return the linear and tree hash in hexadecimal format
return linear_hash.hexdigest(), tree_hash_digest.hex()

