    # Decrease the in-degree of the dependencies of the current revision
    for dep in rev._normalized_down_revisions:
        if dep in in_degree:
            in_degree[dep] -= 1
            if in_degree[dep] == 0:
                queue.append(dep)

# Check if there is a cycle in the graph
if any(in_degree.values()):
    raise CycleDetected(sorted_revisions)

# Check if there are multiple heads
if len(heads) > 1:
    raise MultipleHeads(heads, None)

return sorted_revisions

# Create a dictionary to store the number of incoming edges for each revision
in_degree = {rev.revision: 0 for rev in revisions}

# Create a dictionary to store the list of outgoing edges for each revision
out_edges = {rev.revision: set() for rev in revisions}

# Iterate over the revisions and update the in_degree and out_edges dictionaries
for rev in revisions:
    for next_rev_id in rev._normalized_down_revisions:
        if next_rev_id not in in_degree:
            continue
        in_degree[next_rev_id] += 1
        out_edges[rev.revision].add(next_rev_id)

# Create a queue to store the revisions with no incoming edges
queue = collections.deque(
    [revision for revision, degree in in_degree.items() if degree == 0]
)

# Create a list to store the sorted revision ids
sorted_revisions = []

# Iterate over the queue until it becomes empty
while queue:
    # Pop the first revision from the queue
    rev_id = queue.popleft()

    # Add the revision id to the sorted revisions list
    sorted_revisions.append(rev_id)

    # Iterate over the outgoing edges of the current revision
    for next_rev_id in out_edges[rev_id]:
        # Decrement the in-degree of the next revision
        in_degree[next_rev_id] -= 1

        # If the in-degree becomes 0, add it to the queue
        if in_degree[next_rev_id] == 0:
            queue.append(next_rev_id)

# Check if there are any cycles in the graph
if len(sorted_revisions) != len(revisions):
    raise CycleDetected(
        [
            rev_id
            for rev_id, degree in in_degree.items()
            if degree > 0
        ]

# Create a dictionary to store the number of incoming edges for each revision
incoming_edges = {revision: 0 for revision in revisions}

# Create a dictionary to store the list of downstream revisions for each revision
downstream_revisions = {
    revision: set() for revision in revisions
}

# Iterate through the revisions and update the incoming edges and downstream revisions
for revision in revisions:
    for downstream_revision in revision.nextrev:
        downstream_revisions[downstream_revision].add(revision)
        incoming_edges[downstream_revision] += 1

# Create a queue to store the revisions with no incoming edges
queue = deque(
    [revision for revision, count in incoming_edges.items() if count == 0]
)

# Initialize the result list
result = []

# Perform the topological sort
while queue:
    revision = queue.popleft()
    result.append(revision)

    for downstream_revision in downstream_revisions[revision]:
        incoming_edges[downstream_revision] -= 1
        if incoming_edges[downstream_revision] == 0:
            queue.append(downstream_revision)

# Check if there are any cycles in the graph
if any(count > 0 for count in incoming_edges.values()):
    raise ValueError("Cycle detected in the graph")

# Return the result
return result

