# parse them and convert them to JSON...
data = defaultdict(dict)

for section in config_parser.sections():
    # If it's not a host declaration, ignore it
    if not section.startswith(":"):
        continue

    # Parse the hosts section
    section_bits = section.split(":")
    hostname = section_bits[1]

    # Loop through the options (the list of groups)
    for option in config_parser.options(section):
        data[hostname][option] = {}

        # Loop through the hosts/ips in the group
        for host in config_parser.get(section, option).split(","):
            host = host.strip()

            # Skip blank/invalid hosts
            if not host:
                continue

            data[hostname][option][host] = config_parser.get(host, "ansible_host")

return data

