    for key, value in jobconf.items():
        # If the value is not None, add it to the combined job configuration
        if value is not None:
            # If the value is a string, add it as-is
            if isinstance(value, str):
                combined_jobconf[key] = value
            # If the value is a boolean, convert it to a string representation
            elif isinstance(value, bool):
                combined_jobconf[key] = str(value).lower()
            # If the value is a number, convert it to a string representation
            elif isinstance(value, (int, float)):
                combined_jobconf[key] = str(value)
            # If the value is a list or tuple, convert it to a string representation
            elif isinstance(value, (list, tuple)):
                combined_jobconf[key] = ','.join(str(item) for item in value)
            # If the value is a dictionary, convert it to a string representation
            elif isinstance(value, dict):
                combined_jobconf[key] = ','.join('%s=%s' % (k, v) for k, v in value.items())
            # If the value is not a string, boolean, number, list, tuple, or dictionary, raise a TypeError
            else:
                raise TypeError('Jobconf value must be a string, boolean, number, list, tuple, or dictionary')

# Return the combined job configuration dictionary
return combined_jobconf

