while True:
    logger.info("Starting run")

    # Get artifacts from sources.
    artifacts = collections.deque()
    for name, source in self.sources.items():
        logger.debug(f"Running source '{name}'")
        try:
            artifacts.extend(source.run())
        except threatingestor.exceptions.SourceError:
            logger.exception(f"Error running source '{name}'")

    # Process artifacts through operators.
    for name, operator in self.operators.items():
        logger.debug(f"Running operator '{name}'")
        try:
            operator.run(artifacts)
        except threatingestor.exceptions.OperatorError:
            logger.exception(f"Error running operator '{name}'")

    # Update state.
    for artifact in artifacts:
        if not self._is_whitelisted(artifact):
            self.statedb.add(artifact)

    # If we're not running as a daemon, exit.
    if not self.config.daemon():
        logger.info("Not running as daemon; exiting")
        break

    # Sleep for the configured interval.
    logger.info("Sleeping")
    time.sleep(self.config.interval())

