def _discretize(df: pd.DataFrame) -> pd.DataFrame:
    """
    This function discretizes the numerical columns in a pandas DataFrame using a uniform discretization method. It creates a copy of the input DataFrame and discretizes each numerical column using the 'quantile' method.
    Input-Output Arguments
    :param df: pd.DataFrame. The input DataFrame.
    :return: pd.DataFrame. The discretized DataFrame.
    """
    df_copy = df.copy()
    for col in df_copy.columns:
        if df_copy[col].dtype != "object":
            df_copy[col] = pd.qcut(df_copy[col], q=10, labels=False, duplicates="drop")
    return df_copy

