class _ComplementSet(set):
    def __init__(self, wrapped):
        self.wrapped = wrapped
        self.not_in = set()

    def __contains__(self, item):
        if item in self.not_in:
            return False
        return item in self.wrapped

    def __iter__(self):
        return (item for item in self.wrapped if item not in self.not_in)

    def __len__(self):
        return len(self.wrapped) - len(self.not_in)

    def __repr__(self):
        return '%s(%r)' % (self.__class__.__name__, list(self))

    def add(self, item):
        if item in self.not_in:
            self.not_in.remove(item)
        else:
            self.wrapped.add(item)

    def clear(self):
        self.wrapped.clear()
        self.not_in.clear()

    def discard(self, item):
        if item in self.wrapped:
            self.wrapped.discard(item)
        else:
            self.not_in.add(item)

    def remove(self, item):
        if item in self.wrapped:
            self.wrapped.remove(item)
        else:
            self.not_in.remove(item)

    def update(self, *args, **kwargs):
        self.wrapped.update(*args, **kwargs)

